// Package shellcomp enables and disables ws's shell completion: which rc file
// each shell reads, the marked block `ws completion enable` keeps in it, and
// whether that block is there. `ws completion enable|disable` and the TUI's
// Workspace screen share it, so they cannot drift. The completion scripts
// themselves are generated by the CLI (`ws completion bash|zsh|fish`).
package shellcomp

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/mugenkunou/ws-tool/internal/plan"
)

// Sentinel markers for idempotent enable/disable.
const (
	MarkerStart = "# >>> ws shell completion >>>"
	MarkerEnd   = "# <<< ws shell completion <<<"
)

// Shells are the shells ws completes.
var Shells = []string{"bash", "zsh", "fish"}

// Action IDs of the plans below.
const (
	EnableID  = "completion-enable"
	DisableID = "completion-disable"
)

// Detect resolves the current shell from $SHELL: its base name, or bash when
// $SHELL is unset. A shell ws does not complete is returned as is; Resolve
// rejects it.
func Detect() string {
	s := os.Getenv("SHELL")
	if s == "" {
		return "bash" // safe default on Linux
	}
	return filepath.Base(s)
}

// Resolve is the shell a command works on: name (the --shell value) when
// given, else the one $SHELL names. Any shell but bash, zsh or fish is an error.
func Resolve(name string) (string, error) {
	sh := strings.ToLower(strings.TrimSpace(name))
	if sh == "" {
		sh = Detect()
	}
	if sh != "bash" && sh != "zsh" && sh != "fish" {
		return "", fmt.Errorf("unsupported shell %q (use --shell bash|zsh|fish)", sh)
	}
	return sh, nil
}

// RC returns the rc file path and the line that loads completion for shell.
func RC(shell string) (rcPath, evalLine string, err error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", "", err
	}
	switch shell {
	case "bash":
		return filepath.Join(home, ".bashrc"), `eval "$(ws completion bash)"`, nil
	case "zsh":
		return filepath.Join(home, ".zshrc"), `eval "$(ws completion zsh)"`, nil
	case "fish":
		confDir := os.Getenv("XDG_CONFIG_HOME")
		if confDir == "" {
			confDir = filepath.Join(home, ".config")
		}
		return filepath.Join(confDir, "fish", "conf.d", "ws.fish"), "ws completion fish | source", nil
	default:
		return "", "", fmt.Errorf("unsupported shell: %s", shell)
	}
}

// Status is where ws completion stands for one shell.
type Status struct {
	Shell   string
	RC      string // the rc file the shell reads
	Enabled bool   // the rc file holds ws's marked block
	Current bool   // the shell $SHELL names
}

// StatusOf reads whether completion is enabled for shell. A missing rc file
// means it is not.
func StatusOf(shell string) (Status, error) {
	rc, _, err := RC(shell)
	if err != nil {
		return Status{}, err
	}
	content, _ := os.ReadFile(rc)
	return Status{Shell: shell, RC: rc, Enabled: HasMarker(string(content)), Current: shell == Detect()}, nil
}

// Statuses reads StatusOf for every shell in Shells.
func Statuses() ([]Status, error) {
	out := make([]Status, 0, len(Shells))
	for _, sh := range Shells {
		st, err := StatusOf(sh)
		if err != nil {
			return nil, err
		}
		out = append(out, st)
	}
	return out, nil
}

// EnablePlan returns the rc file and the one action that loads completion
// there. The actions are empty when the block is already current.
func EnablePlan(shell string) (rcPath string, actions []plan.Action, err error) {
	rcPath, line, err := RC(shell)
	if err != nil {
		return "", nil, err
	}
	content, _ := os.ReadFile(rcPath) // a missing rc file is created
	updated := WithBlock(string(content), Block(line))
	if updated == string(content) {
		return rcPath, nil, nil
	}
	return rcPath, []plan.Action{{
		ID:          EnableID,
		Description: fmt.Sprintf("Load ws completion from %s", rcPath),
		Execute: func() error {
			if err := os.MkdirAll(filepath.Dir(rcPath), 0o755); err != nil {
				return err
			}
			return os.WriteFile(rcPath, []byte(updated), 0o644)
		},
	}}, nil
}

// DisablePlan returns the rc file and the one action that removes ws's block
// from it. The actions are empty when the block is not there.
func DisablePlan(shell string) (rcPath string, actions []plan.Action, err error) {
	rcPath, _, err = RC(shell)
	if err != nil {
		return "", nil, err
	}
	content, _ := os.ReadFile(rcPath)
	if !HasMarker(string(content)) {
		return rcPath, nil, nil
	}
	cleaned := RemoveBlock(string(content))
	return rcPath, []plan.Action{{
		ID:          DisableID,
		Description: fmt.Sprintf("Remove ws completion from %s", rcPath),
		Execute:     func() error { return os.WriteFile(rcPath, []byte(cleaned), 0o644) },
	}}, nil
}

// Block is the marked block that loads completion with evalLine.
func Block(evalLine string) string {
	return fmt.Sprintf("%s\n%s\n%s\n", MarkerStart, evalLine, MarkerEnd)
}

// HasMarker returns true if the text contains our sentinel markers.
func HasMarker(text string) bool {
	return strings.Contains(text, MarkerStart)
}

// WithBlock returns text with the marked block set to block: an existing block
// (current or older line) is replaced in place, unmarked lines that load ws
// completion are removed, and a missing block is appended.
func WithBlock(text, block string) string {
	if HasMarker(text) {
		start := strings.Index(text, MarkerStart)
		end := strings.Index(text, MarkerEnd)
		if end > start {
			end += len(MarkerEnd)
			if end < len(text) && text[end] == '\n' {
				end++
			}
			return RemoveStaleLines(text[:start]) + block + RemoveStaleLines(text[end:])
		}
	}
	cleaned := RemoveStaleLines(text)
	if cleaned != "" && !strings.HasSuffix(cleaned, "\n") {
		cleaned += "\n"
	}
	if cleaned != "" {
		cleaned += "\n"
	}
	return cleaned + block
}

// RemoveBlock removes everything between (and including) the sentinel
// markers. Preserves the rest of the file exactly.
func RemoveBlock(text string) string {
	start := strings.Index(text, MarkerStart)
	if start < 0 {
		return text
	}
	end := strings.Index(text, MarkerEnd)
	if end < 0 {
		return text
	}
	end += len(MarkerEnd)
	// Also consume the trailing newline after the end marker.
	if end < len(text) && text[end] == '\n' {
		end++
	}
	// Also consume a leading newline before the start marker.
	if start > 0 && text[start-1] == '\n' {
		start--
	}
	return text[:start] + text[end:]
}

// RemoveStaleLines removes any pre-existing ws completion lines
// that were manually added before the sentinel system existed.
// This handles the duplicate-entry problem.
func RemoveStaleLines(text string) string {
	lines := strings.Split(text, "\n")
	var cleaned []string
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if isStaleLine(trimmed) {
			continue
		}
		cleaned = append(cleaned, line)
	}
	return strings.Join(cleaned, "\n")
}

// isStaleLine detects old-style manual completion setup lines.
func isStaleLine(line string) bool {
	// Common patterns people might have added manually:
	//   eval "$(ws completions bash)"
	//   source <(ws completions bash)
	//   ws completions bash | source
	if strings.Contains(line, "ws completions") || strings.Contains(line, "ws completion ") || strings.Contains(line, "ws-completions") {
		// Don't match comment lines (they're harmless).
		if strings.HasPrefix(line, "#") {
			return false
		}
		return true
	}
	return false
}
